after.content:
        }
        if (outcome == null || decidedAt == null) throw new IllegalArgumentException("decision fields must not be null");
    }

    public static Decision allow(Request request, Instant decidedAt) {
        return new Decision(request.permissionId(), request.revision(), request.revision() + 1,
                Outcome.ALLOW, decidedAt);
    }

    public static Decision deny(Request request, Instant decidedAt) {
        return new Decision(request.permissionId(), request.revision(), request.revision() + 1,
                Outcome.DENY, decidedAt);
    }
}

enum Outcome { ALLOW, DENY }
